function lsGet(k, d){ try{ const v = localStorage.getItem(NS+k); return v ? JSON.parse(v) : d; }catch(e){ return d; } }
let storageWarningShown = false;
function lsSet(k, v){
  try {
    localStorage.setItem(NS+k, JSON.stringify(v));
    if (typeof window.__nativePersist === "function") window.__nativePersist(NS+k, v);
    return true;
  }
  catch(e){
    if (!storageWarningShown && document.getElementById("toast")) {
      storageWarningShown = true;
      toast("اس براؤزر میں محفوظ نہیں ہو سکا۔ بیک اپ فائل بنا لیں۔");
    }
    return false;
  }
}

function iso(d){ return d.getFullYear()+"-"+String(d.getMonth()+1).padStart(2,"0")+"-"+String(d.getDate()).padStart(2,"0"); }
function parseIso(s){ const [y,m,d] = s.split("-").map(Number); return new Date(y, m-1, d); }
function addDays(s, n){ const d = parseIso(s); d.setDate(d.getDate()+n); return iso(d); }
function todayIso(){ return iso(new Date()); }
function niceDate(s){ const d = parseIso(s); return DAYS[d.getDay()]+"، "+d.getDate()+" "+MONTHS[d.getMonth()]+" "+d.getFullYear(); }

