const CATEGORY_FALLBACK = {"tahajjud":"tahajjud","toilet":"toilet","wudu":"wudu","prep":"prep","libas":"libas","masjid":"masjid","ishraq":"ishraq","fajr_dhikr":"fajr","ishraq_chaasht":"ishraq_chaasht","work":"work","work_duties":"work","work_time":"work","heart":"work","heart_speech":"work","heart_taqwa":"work","akhlaq":"akhlaq","akhlaq_road":"akhlaq","akhlaq_talk":"akhlaq","akhlaq_majlis":"akhlaq","akhlaq_daily":"akhlaq","akhlaq_kindness":"akhlaq","akhlaq_care":"akhlaq","family":"akhlaq","family_relations":"akhlaq","family_care":"akhlaq","family_entry":"akhlaq","food":"food","food_sunnah":"food","food_method":"food","food_after":"food","zuhr":"zuhr","qailula":"sleep","asr":"asr","maghrib":"maghrib","isha":"isha","sleep":"sleep","fajr":"fajr"};
function refineSavedCategories(doc){
  if (!doc || !Array.isArray(doc.cats) || !Array.isArray(doc.items) || Number(doc.taxonomyVersion) >= 3) return false;
  const currentIds = new Set(doc.cats.map(c => c.id));
  const approvedIds = new Set(APPROVED_CATEGORIES.map(c => c.id));
  // Preserve custom categories and their personal routines in the original order.
  const personalCats = doc.cats.filter(c => !OLD_DEFAULT_CATEGORY_IDS.has(c.id) && !approvedIds.has(c.id));
  const personalIds = new Set(personalCats.map(c => c.id));
  for (const item of doc.items){
    if (OLD_DEFAULT_CATEGORY_IDS.has(item.c) || approvedIds.has(item.c)){
      const assigned = Object.prototype.hasOwnProperty.call(APPROVED_ASSIGNMENT,item.id)
        ? APPROVED_ASSIGNMENT[item.id] : (CATEGORY_FALLBACK[item.c] || item.c);
      item.c = assigned;
    } else if (!personalIds.has(item.c)) {
      // Protect imported/custom records from an orphaned category reference.
      const originalCategory = doc.cats.find(c => c.id === item.c);
      if (originalCategory){ personalCats.push(originalCategory); personalIds.add(item.c); }
    }
  }
  doc.cats = APPROVED_CATEGORIES.map(c=>({...c})).concat(personalCats);
  doc.taxonomyVersion = 3;
  return true;
}
const hadLocalCategoryUpgrade = refineSavedCategories(cfg);
