function items(){ return cfg.items; }
function catName(id){ const c = cfg.cats.find(c => c.id === id); return c ? c.name : ""; }
function dayRec(date, create){
  if (!recs[date] && create) recs[date] = {s:{}, notes:{}, u:0};
  return recs[date] || {s:{}, notes:{}};
}
function statusOf(id, date){ return (dayRec(date || ui.date).s || {})[id] || ""; }

function stats(list, date){
  const r = dayRec(date || ui.date); const s = r.s || {};
  let y=0,p=0,n=0,a=0;
  for (const it of list){
    const v = s[it.id];
    if (v === "y") y++;
    else if (v === "p") p++;
    else if (v === "n") n++;
    else if (v === "a") a++;
  }
  const total = list.length, active = total-a;
  return {total, active, y, p, n, a, u:Math.max(0, active-y-p-n)};
}
function pctOf(st){ if (!st.active) return 0; return ((st.y + (prefs.weighted ? st.p*.5 : 0)) / st.active) * 100; }
function fmtPct(v){ return (Math.round(v*10)/10).toFixed(v >= 99.95 || v === 0 ? 0 : 1) + "%"; }

/* ---------- Persistence: this device + cloud when available ---------- */
const dirty = new Set();
let saveTimer = null;
function persist(kind, monthKey){
  if (kind === "cfg"){ lsSet("cfg", cfg); dirty.add("cfg"); }
  if (kind === "recs"){ lsSet("recs", recs); dirty.add("r-" + monthKey); }
  if (kind === "stars"){ lsSet("stars", stars); dirty.add("stars"); }
  clearTimeout(saveTimer); saveTimer = setTimeout(flushCloud, 1500);
}
function touchDay(date){ const r = dayRec(date, true); r.u = Date.now(); persist("recs", date.slice(0,7)); }

const cloud = {db:null, uid:null, on:false, busy:false, months:new Set()};
function col(){ return cloud.db.collection("data/users/" + cloud.uid); }
function monthBody(mk){
  const days = {};
  for (const [d, r] of Object.entries(recs)) if (d.slice(0,7) === mk) days[d] = r;
  return {days, u: Date.now()};
}
async function flushCloud(){
  if (!cloud.on || cloud.busy || !dirty.size) return;
  cloud.busy = true;
  try{
    while (dirty.size && cloud.on){
      const key = dirty.values().next().value; dirty.delete(key);
      let body;
      if (key === "cfg") body = cfg;
      else if (key === "stars") body = stars;
      else body = monthBody(key.slice(2));
      try{ await col().doc(key).set(clone(body)); }
      catch(e){
        const code = e && e.code;
        if (code === "unavailable" || code === "resource_exhausted"){ dirty.add(key); setTimeout(flushCloud, 4000 + Math.random()*2000); break; }
        if (code === "quota_exceeded"){ toast("کلاؤڈ میں جگہ ختم ہو گئی۔ ریکارڈ اس ڈیوائس پر محفوظ ہے۔"); }
        cloud.on = false; setSync();
      }
    }
  } finally { cloud.busy = false; }
}
async function loadMonth(mk){
  if (!cloud.on || cloud.months.has(mk)) return false;
  cloud.months.add(mk);
  try{
    const snap = await col().doc("r-" + mk).get();
    if (!snap.exists) { if (Object.keys(recs).some(d => d.slice(0,7) === mk)) { dirty.add("r-"+mk); flushCloud(); } return false; }
    const days = (snap.data() || {}).days || {};
    let changed = false, localNewer = false;
    for (const [d, r] of Object.entries(days)){
      if (!recs[d] || (r.u || 0) > (recs[d].u || 0)){ recs[d] = clone(r); changed = true; }
    }
    for (const [d, r] of Object.entries(recs)) if (d.slice(0,7) === mk && (!days[d] || (r.u||0) > (days[d].u||0))) localNewer = true;
    if (changed) lsSet("recs", recs);
    if (localNewer){ dirty.add("r-" + mk); flushCloud(); }
    return changed;
  }catch(e){ return false; }
}
async function initCloud(){
  if (!window.claude || typeof window.claude.use !== "function") return;
  try{
    const [db, user] = await Promise.all([window.claude.use("db"), window.claude.use("user")]);
    if (!db || !user) return;
    const uid = await user.id(); if (!uid) return;
    cloud.db = db; cloud.uid = uid; cloud.on = true;
    const [c, s] = await Promise.all([col().doc("cfg").get(), col().doc("stars").get()]);
    let changed = false;
    if (c.exists){
      const rc = c.data() || {};
      if ((rc.u||0) > (cfg.u||0) && Array.isArray(rc.items)){
        cfg = clone(rc);
        const upgradedCloud = refineSavedCategories(cfg);
        if (upgradedCloud){ cfg.u = Date.now(); dirty.add("cfg"); }
        lsSet("cfg", cfg); changed = true;
      } else if ((cfg.u||0) > (rc.u||0) || hadLocalCategoryUpgrade){
        if (hadLocalCategoryUpgrade){ cfg.u = Date.now(); lsSet("cfg",cfg); }
        dirty.add("cfg");
      }
    } else if (cfg.u || hadLocalCategoryUpgrade){
      if (hadLocalCategoryUpgrade){ cfg.u = Date.now(); lsSet("cfg",cfg); }
      dirty.add("cfg");
    }
    if (s.exists){ const rs = s.data(); if ((rs.u||0) > (stars.u||0)){ stars = clone(rs); lsSet("stars", stars); changed = true; } else if ((stars.u||0) > (rs.u||0)) dirty.add("stars"); }
    else if (stars.u) dirty.add("stars");
    const m1 = ui.date.slice(0,7), m0 = addDays(ui.date.slice(0,7)+"-01", -1).slice(0,7);
    const a = await loadMonth(m1), b = await loadMonth(m0);
    setSync();
    if (changed || a || b) renderAll();
    flushCloud();
  }catch(e){ cloud.on = false; setSync(); }
}
function setSync(){
  const el = document.getElementById("syncState");
  if (el){ el.className = "sync" + (cloud.on ? " cloud" : ""); el.lastChild.textContent = cloud.on ? "آپ کے اکاؤنٹ میں محفوظ ہو رہا ہے (ہر ڈیوائس پر)" : "صرف اس براؤزر میں محفوظ ہے"; }
}

/* ---------- Text formatting: Arabic phrases in a Naskh face ---------- */
const HARAKAT = /[ً-ْٰ]/;
function fmtText(t, q){
  const tokens = String(t).split(/(\s+)/);
  let out = "", run = [];
  const flush = () => { if (run.length){ out += '<span class="ar">' + run.join("") + "</span>"; run = []; } };
  for (let i=0;i<tokens.length;i++){
    const tk = tokens[i];
    if (/^\s+$/.test(tk)){ if (run.length) run.push(tk); else out += tk; continue; }
    const isAr = HARAKAT.test(tk.replace(/\u0650(?=[^\u0600-\u06FF]*$)/, "")) || tk === "ﷺ";
    if (isAr) run.push(hl(esc(tk), q)); else {
      if (run.length && /^\s+$/.test(run[run.length-1])){ const sp = run.pop(); flush(); out += sp; } else flush();
      out += hl(esc(tk), q);
    }
  }
  flush();
  return out;
}
function hl(html, q){
  if (!q) return html;
  const qq = esc(q).replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
  return html.replace(new RegExp(qq, "g"), m => "<mark>" + m + "</mark>");
}

