/* ---------- Rendering ---------- */
function gradeText(p){
  if (p >= 85) return "ما شاء اللہ، ممتاز";
  if (p >= 65) return "ما شاء اللہ، بہت عمدہ";
  if (p >= 50) return "شاباش، تسلی بخش";
  if (p > 0) return "مزید ہمت درکار ہے";
  return "آج کا ریکارڈ ابھی شروع نہیں ہوا";
}
function renderSummary(){
  const st = stats(items());
  const p = pctOf(st);
  $("#pct").textContent = fmtPct(p);
  $("#ringArc").style.strokeDashoffset = 263.9 - 263.9 * p / 100;
  $("#grade").textContent = gradeText(p);
  $("#formula").textContent = prefs.weighted
    ? `(${st.y} + ½ × ${st.p}) ÷ ${st.active} قابلِ اطلاق`
    : `${st.y} ÷ ${st.active} قابلِ اطلاق معمولات`;
  $("#weightBtn").setAttribute("aria-checked", prefs.weighted ? "true" : "false");
  const seg = (v, c) => st.total ? `<span style="width:${v/st.total*100}%;background:${c}"></span>` : "";
  $("#bar").innerHTML = seg(st.y,"var(--done)") + seg(st.p,"var(--part)") + seg(st.n,"var(--miss)") + seg(st.a,"var(--na)");
  $("#legend").innerHTML = [["مکمل",st.y,"var(--done)"],["جزوی",st.p,"var(--part)"],["رہ گیا",st.n,"var(--miss)"],["باقی",st.u,"var(--line)"],["لاگو نہیں",st.a,"var(--na)"]]
    .map(([l,v,c]) => `<div><span><i class="dot" style="background:${c}"></i>${l}</span><b>${v}</b></div>`).join("");
  $("#subtitle").textContent = `${st.total} مسنون اعمال کی فہرست`;
  const tbc = $("#tbCount"); if (tbc){ tbc.textContent = `${st.y} / ${st.active}  ·  ${fmtPct(p)}`; $("#miniArc").style.strokeDashoffset = 94.25 - 94.25 * p / 100;
    $("#tbLabel").textContent = ui.date === todayIso() ? "آج کے معمولات مکمل" : niceDate(ui.date); }
}
function renderHistory(){
  const end = ui.date > todayIso() ? ui.date : todayIso();
  const days = []; for (let i=29;i>=0;i--) days.push(addDays(end, -i));
  const list = items();
  let sum=0, cnt=0, streak=0, streakOpen=true;
  const html = days.map(d => {
    const has = recs[d] && Object.keys(recs[d].s||{}).length;
    const p = has ? pctOf(stats(list, d)) : 0;
    if (has){ sum += p; cnt++; }
    return `<button data-d="${d}" class="${d===ui.date?"sel":""} ${has?"":"empty"}" title="${esc(niceDate(d))}: ${has?fmtPct(p):"کوئی ریکارڈ نہیں"}" aria-label="${esc(niceDate(d))}"><i style="height:${Math.max(p, has?3:0)}%"></i></button>`;
  }).join("");
  for (let i=days.length-1;i>=0;i--){ const d = days[i]; const has = recs[d] && Object.keys(recs[d].s||{}).length; if (d === todayIso() && !has) continue; if (has && pctOf(stats(list,d)) >= 50) streak++; else break; }
  $("#hist").innerHTML = html;
  const f = parseIso(days[0]), t = parseIso(days[29]);
  $("#histFrom").textContent = f.getDate()+" "+MONTHS[f.getMonth()];
  $("#histTo").textContent = t.getDate()+" "+MONTHS[t.getMonth()];
  $("#histStats").innerHTML = `<span>اوسط: <b>${cnt?fmtPct(sum/cnt):"—"}</b></span><span>ریکارڈ شدہ دن: <b>${cnt}</b></span><span>مسلسل ۵۰٪+: <b>${streak}</b> دن</span>`;
}
