function normalized(s){
  return String(s||"").normalize("NFKC").toLowerCase()
    .replace(/[\u064b-\u065f\u0670\u06d6-\u06ed\u0640]/g, "")
    .replace(/[يى]/g, "ی").replace(/ك/g, "ک").replace(/\s+/g, " ").trim();
}
function matches(it, idx){
  const s = statusOf(it.id);
  if (ui.status === "todo" && s) return false;
  if (["y","p","n","a"].includes(ui.status) && s !== ui.status) return false;
  if (ui.status === "star" && !stars.ids[it.id]) return false;
  const q = ui.q.trim();
  if (q){
    const n = q.replace(/^#/,"");
    if (/^\d+$/.test(n)) return String(idx+1) === n;
    return normalized(it.t + " " + it.r + " " + catName(it.c)).includes(normalized(q));
  }
  return true;
}
