/* ---------- Toast & modal ---------- */
let toastT;
function toast(msg){ const t = $("#toast"); t.textContent = msg; t.classList.add("show"); clearTimeout(toastT); toastT = setTimeout(() => t.classList.remove("show"), 2200); }
function modal(title, bodyHtml, onMount){
  const previous = document.activeElement;
  const priorOverflow = document.body.style.overflow;
  const ov = document.createElement("div"); ov.className = "ov";
  ov.innerHTML = `<div class="modal" role="dialog" aria-modal="true" aria-label="${esc(title)}" tabindex="-1"><div class="modal-h"><h4>${esc(title)}</h4><button class="iconbtn" data-close aria-label="بند کریں">${I.close}</button></div>${bodyHtml}</div>`;
  let active = true;
  const close = () => {
    if (!active) return; active = false;
    ov.remove(); document.removeEventListener("keydown", onKey);
    document.body.style.overflow = priorOverflow;
    if (previous && previous.isConnected && previous.focus) previous.focus();
  };
  const onKey = e => {
    if (e.key === "Escape") {e.preventDefault(); close();}
    if (e.key === "Tab") {
      const els = Array.from(ov.querySelectorAll('button:not([disabled]), input:not([disabled]), textarea:not([disabled]), select:not([disabled]), [tabindex="0"]')).filter(el => el.getClientRects().length);
      if (!els.length) {e.preventDefault();return;}
      const i = els.indexOf(document.activeElement);
      if (e.shiftKey && (i <= 0)) {e.preventDefault(); els[els.length-1].focus();}
      else if (!e.shiftKey && i === els.length-1) {e.preventDefault(); els[0].focus();}
    }
  };
  ov.addEventListener("click", e => { if (e.target === ov || e.target.closest("[data-close]")) close(); });
  document.addEventListener("keydown", onKey);
  document.body.appendChild(ov);
  document.body.style.overflow = "hidden";
  if (onMount) onMount(ov, close);
  ov.querySelector("[data-close]").focus();
  return close;
}
/* two-step confirm on a button (no native dialogs in the viewer) */
function confirmBtn(btn, label, fn){
  if (btn.dataset.armed){ fn(); return; }
  btn.dataset.armed = "1"; const old = btn.innerHTML; btn.textContent = label;
  setTimeout(() => { if (btn.isConnected){ delete btn.dataset.armed; btn.innerHTML = old; } }, 3000);
}

/* ---------- Actions ---------- */
function setStatus(id, v){
  const r = dayRec(ui.date, true);
  rememberUndo(ui.date, "تبدیلی محفوظ ہو گئی");
  if (r.s[id] === v) delete r.s[id]; else r.s[id] = v;
  touchDay(ui.date);
  const el = document.querySelector(`.item[data-id="${CSS.escape(id)}"]`);
  const idx = items().findIndex(it => it.id === id);
  if (el && ui.status === "all" && idx >= 0){ el.outerHTML = itemHtml(items()[idx], idx); markClamps(); }
  else renderList();
  refreshCounts();
}
let cfgTimer;
function cfgChanged(rerender){
  cfg.u = Date.now();
  clearTimeout(cfgTimer);
  persist("cfg");
  if (rerender){ renderList(); refreshCounts(); }
}
function moveItem(id, dir){
  const list = items(); const i = list.findIndex(it => it.id === id); if (i < 0) return;
  let j = i + dir;
  if (CATS_ON){ while (j >= 0 && j < list.length && list[j].c !== list[i].c) j += dir; }
  if (j < 0 || j >= list.length) return;
  [list[i], list[j]] = [list[j], list[i]];
  cfgChanged(true);
  const el = document.querySelector(`.item[data-id="${CSS.escape(id)}"] [data-act="${dir<0?"up":"down"}"]`); if (el) el.focus();
}
function addItem(catId){
  const it = {id: "n" + Date.now().toString(36), t:"", r:"", c: catId || (cfg.cats[0] && cfg.cats[0].id) || ""};
  const list = items();
  let at = list.length;
  if (CATS_ON){ for (let k = list.length-1; k >= 0; k--) if (list[k].c === it.c){ at = k+1; break; } }
  list.splice(at, 0, it);
  cfgChanged(true);
  const ta = document.querySelector(`.item[data-id="${it.id}"] textarea`); if (ta){ ta.focus(); ta.scrollIntoView({block:"center"}); }
}
function delItem(id){
  cfg.items = items().filter(it => it.id !== id);
  cfgChanged(true); toast("معمول حذف ہو گیا");
}
function moveCat(id, dir){
  const i = cfg.cats.findIndex(c => c.id === id), j = i + dir;
  if (j < 0 || j >= cfg.cats.length) return;
  [cfg.cats[i], cfg.cats[j]] = [cfg.cats[j], cfg.cats[i]];
  cfgChanged(true);
}
function delCat(id){
  if (cfg.cats.length <= 1){ toast("کم از کم ایک زمرہ ضروری ہے"); return; }
  const i = cfg.cats.findIndex(c => c.id === id);
  const target = cfg.cats[i > 0 ? i-1 : 1];
  const n = items().filter(it => it.c === id).length;
  items().forEach(it => { if (it.c === id) it.c = target.id; });
  cfg.cats.splice(i, 1);
  if (ui.cat === id) ui.cat = "all";
  cfgChanged(true);
  toast(n ? `${n} معمولات «${target.name}» میں منتقل ہو گئے` : "زمرہ حذف ہو گیا");
}
function addCat(){
  const c = {id: "c" + Date.now().toString(36), name: "نیا زمرہ"};
  cfg.cats.push(c); cfgChanged(true);
  const inp = document.querySelector(`.sec[data-cat="${c.id}"] input`); if (inp){ inp.focus(); inp.select(); inp.scrollIntoView({block:"center"}); }
}
function setDate(d){
  ui.date = d; ui.openNotes = {};
  renderAll();
  const mk = d.slice(0,7);
  loadMonth(mk).then(ch => { if (ch) renderAll(); });
}

/* ---------- Share summary ---------- */
function summaryText(){
  const st = stats(items()); const p = pctOf(st);
  let t = `معمولاتِ یومیہ — ${niceDate(ui.date)}\n`;
  t += `مکمل: ${st.y} / ${st.active} قابلِ اطلاق (${fmtPct(p)})\nجزوی: ${st.p} · رہ گیا: ${st.n} · باقی: ${st.u} · لاگو نہیں: ${st.a}\n`;
  if (CATS_ON){
    t += "\n";
    for (const {c, st: s} of catStats()) if (s.total) t += `${c.name}: ${s.y}/${s.active}${s.p?` (جزوی ${s.p})`:""}${s.a?` (لاگو نہیں ${s.a})`:""}\n`;
  }
  const missed = items().filter(it => statusOf(it.id) === "n");
  if (missed.length && missed.length <= 12){
    t += "\nرہ جانے والے:\n" + missed.map(it => "• " + it.t.split(/[۔:]/)[0].slice(0, 70)).join("\n") + "\n";
  }
  return t.trim();
}
function openShare(){
  const txt = summaryText();
  modal("آج کا خلاصہ", `<p class="muted">یہ متن کاپی کر کے واٹس ایپ یا کسی بھی جگہ بھیج سکتے ہیں۔</p><textarea class="sharetext" id="shareTxt" readonly>${esc(txt)}</textarea><div class="panel-actions"><button class="btn primary" id="copyShare">متن کاپی کریں</button></div>`, (ov) => {
    ov.querySelector("#copyShare").addEventListener("click", () => {
      const ta = ov.querySelector("#shareTxt");
      const fallback = () => { ta.focus(); ta.select(); toast("متن منتخب ہے، اب کاپی کر لیں"); };
      try{ navigator.clipboard.writeText(txt).then(() => toast("خلاصہ کاپی ہو گیا"), fallback); }catch(e){ fallback(); }
    });
  });
}

/* ---------- Menu: tasbeeh, backup ---------- */
async function saveJsonFile(content, name){
  if (typeof window.__nativeExportBackup === "function") {
    try {
      await window.__nativeExportBackup(content, name);
      toast("بیک اَپ محفوظ کرنے یا شیئر کرنے کا آپشن کھل گیا ہے");
      return;
    } catch(error) {
      console.warn("Android backup share failed", error);
      toast("بیک اَپ شیئر نہیں ہو سکا، متبادل طریقہ آزما رہے ہیں");
    }
  }
  const blob = new Blob([content], {type:"application/json;charset=utf-8"});
  const url = URL.createObjectURL(blob);
  try {
    const a = document.createElement("a"); a.href = url; a.download = name;
    document.body.appendChild(a); a.click(); a.remove();
    toast("فائل محفوظ کرنے کے لیے ڈاؤن لوڈ شروع ہوگیا");
  } finally { setTimeout(() => URL.revokeObjectURL(url), 4000); }
}
function exportBackup(){
  const body = JSON.stringify({app:"mamulat", mode:MODE, v:3, exported:new Date().toISOString(), cfg, recs, stars, prefs, tas}, null, 2);
  try {saveJsonFile(body, `mamulat-backup-${todayIso()}.json`);}
  catch(e){ modal("بیک اپ", `<p>ڈاؤن لوڈ دستیاب نہیں۔ نیچے دیا گیا متن کاپی کر کے محفوظ کر سکتے ہیں۔</p><textarea class="sharetext" readonly dir="ltr">${esc(body)}</textarea>`); }
}
function importBackup(file){
  if (file.size > 20*1024*1024) { toast("بیک اپ فائل بہت بڑی ہے (۲۰ MB سے زیادہ)"); return; }
  const fr = new FileReader();
  fr.onload = () => {
    try {
      const d = JSON.parse(fr.result);
      if (!d || d.app !== "mamulat" || !d.cfg || !Array.isArray(d.cfg.items) || d.cfg.items.length > 4000) throw new Error("invalid cfg");
      const categories = Array.isArray(d.cfg.cats) && d.cfg.cats.length ? d.cfg.cats : clone(DEF.cats);
      if (categories.length > 300 || !categories.every(c => typeof c.id === "string" && typeof c.name === "string")) throw new Error("invalid categories");
      if (!d.cfg.items.every(it => typeof it.id === "string" && typeof it.t === "string" && typeof it.r === "string")) throw new Error("invalid items");
      const incomingCats = new Set(categories.map(c => c.id));
      if (!d.cfg.items.every(it => incomingCats.has(it.c))) throw new Error("unknown category");
      const incoming = {items:clone(d.cfg.items), cats:clone(categories), taxonomyVersion:Number(d.cfg.taxonomyVersion)||0, u:Date.now()};
      refineSavedCategories(incoming);
      const incomingRecords = d.recs && typeof d.recs === "object" && !Array.isArray(d.recs) ? d.recs : {};
      for (const [date,r] of Object.entries(incomingRecords)) {
        if (!/^\d{4}-\d{2}-\d{2}$/.test(date) || !r || typeof r !== "object" || !r.s || typeof r.s !== "object") throw new Error("invalid records");
      }
      cfg = incoming;
      recs = Object.assign({}, recs, clone(incomingRecords));
      stars = d.stars && d.stars.ids && typeof d.stars.ids === "object" ? clone(d.stars) : stars;
      stars.u = Date.now();
      if (d.prefs && typeof d.prefs === "object"){
        prefs = Object.assign({weighted:false,closed:{},theme:"system",fontScale:1}, d.prefs);
        lsSet("prefs",prefs); applyPrefs();
      }
      if (d.tas && Number.isInteger(d.tas.i) && d.tas.i >= 0 && d.tas.i < DHIKR.length && Number.isInteger(d.tas.n)){
        tas = clone(d.tas); lsSet("tas",tas);
      }
      persist("cfg"); persist("stars"); lsSet("recs",recs);
      for (const mk of new Set(Object.keys(recs).map(k => k.slice(0,7)))) dirty.add("r-"+mk);
      flushCloud();
      ui.cat = "all"; ui.status = "all"; ui.q = ""; $("#q").value = "";
      renderAll(); toast("بیک اپ کامیابی سے بحال ہو گیا");
    } catch(e) {toast("فائل درست نہیں؛ پہلے والا ڈیٹا برقرار ہے"); console.warn("Backup was not imported",e);}
  };
  fr.onerror = () => toast("فائل پڑھنے میں مسئلہ پیش آیا");
  fr.readAsText(file);
}
