$("#resetListBtn").addEventListener("click", e => confirmBtn(e.currentTarget, "یقینی؟ ساری ترامیم ختم ہوں گی", () => {
  cfg = Object.assign(clone(DEF), {u: Date.now()}); persist("cfg"); ui.cat = "all"; renderAll(); toast("اصل فہرست بحال ہو گئی");
}));
$("#menuBtn").addEventListener("click", openMenu);
$("#importFile").addEventListener("change", e => { const f = e.target.files[0]; if (f) importBackup(f); e.target.value = ""; });
let qT; $("#q").addEventListener("input", e => { clearTimeout(qT); qT = setTimeout(() => { ui.q = e.target.value; renderList(); }, 120); });
$("#statusChips").addEventListener("click", e => { const b = e.target.closest("[data-status]"); if (!b) return; ui.status = b.dataset.status; renderStatusChips(); renderList(); updateDock(); });
function pickCat(id){ ui.cat = id; renderNav(); renderList(); updateDock(); if (window.innerWidth >= 980) document.getElementById("mainContent").scrollIntoView({block:"start"}); }
$("#secnav").addEventListener("click", e => { const b = e.target.closest("[data-cat]"); if (b) pickCat(b.dataset.cat); });
$("#catchips").addEventListener("click", e => { const b = e.target.closest("[data-cat]"); if (b) pickCat(b.dataset.cat); });
$("#categorySelect").addEventListener("change", e => pickCat(e.target.value));

const list = $("#list");
list.addEventListener("click", e => {
  if (e.target.id === "addCat") return addCat();
  const cb = e.target.closest("[data-cact]");
  if (cb && cb.tagName !== "INPUT"){
    const sec = cb.closest(".sec"); const cid = sec ? sec.dataset.cat : null; const a = cb.dataset.cact;
    if (a === "toggle"){ prefs.closed[cid] = !prefs.closed[cid]; lsSet("prefs", prefs); sec.classList.toggle("closed"); cb.setAttribute("aria-expanded", !prefs.closed[cid]); }
    if (a === "allyes"){
      const r = dayRec(ui.date, true);
      const ids = items().filter(it => it.c === cid && !r.s[it.id]).map(it => it.id);
      if (!ids.length){ toast("اس زمرے میں سب پہلے سے نشان زد ہیں"); return; }
      rememberUndo(ui.date, `${ids.length} معمولات مکمل نشان زد`);
      ids.forEach(id => r.s[id] = "y");
      touchDay(ui.date); renderList(); refreshCounts();
    }
    if (a === "add") addItem(cid);
    if (a === "up") moveCat(cid, -1);
    if (a === "down") moveCat(cid, 1);
    if (a === "del") confirmBtn(cb, "یقینی؟", () => delCat(cid));
    return;
  }
  const b = e.target.closest("[data-act]"); if (!b || b.tagName === "TEXTAREA" || b.tagName === "INPUT" || b.tagName === "SELECT") return;
  const id = b.closest(".item").dataset.id; const a = b.dataset.act;
  if (a === "st") setStatus(id, b.dataset.v);
  if (a === "star"){ if (stars.ids[id]) delete stars.ids[id]; else stars.ids[id] = true; stars.u = Date.now(); persist("stars"); b.classList.toggle("on", !!stars.ids[id]); b.innerHTML = stars.ids[id] ? I.starF : I.star; renderStatusChips(); }
  if (a === "note"){ ui.openNotes[id] = !ui.openNotes[id]; const box = b.closest(".item").querySelector(".notebox"); box.hidden = !ui.openNotes[id]; if (!box.hidden) box.querySelector("textarea").focus(); }
  if (a === "img"){ const it = items().find(x => x.id === id); modal("اصل عکس (ایکسل سے)", `<div class="imgwrap"><img src="${IMGS[id]}" alt="اصل متن کا عکس"></div><p class="muted" style="margin-top:10px">ٹائپ شدہ متن میں کوئی غلطی نظر آئے تو "ترمیم" سے درست کر لیں۔</p>`); }
  if (a === "up") moveItem(id, -1);
  if (a === "down") moveItem(id, 1);
  if (a === "del") confirmBtn(b, "یقینی؟", () => delItem(id));
});
list.addEventListener("input", e => {
  const t = e.target;
  if (t.dataset.cact === "name"){ const c = cfg.cats.find(c => c.id === t.closest(".sec").dataset.cat); if (c){ c.name = t.value; cfgChanged(false); renderNav(); } return; }
  const a = t.dataset.act; if (!a) return;
  const id = t.closest(".item").dataset.id; const it = items().find(x => x.id === id);
  if (a === "t" && it){ it.t = t.value; cfgChanged(false); }
  if (a === "r" && it){ it.r = t.value; cfgChanged(false); }
  if (a === "notetxt"){
    const writtenDate = ui.date, r = dayRec(writtenDate, true);
    r.notes = r.notes || {};
    if (t.value.trim()) r.notes[id] = t.value; else delete r.notes[id];
    touchDay(writtenDate);
    const nb = t.closest(".item")?.querySelector('[data-act="note"]');
    if (nb) nb.classList.toggle("has", !!t.value.trim());
  }
});
list.addEventListener("change", e => {
  const t = e.target;
  if (t.dataset.act === "cat"){ const it = items().find(x => x.id === t.closest(".item").dataset.id); if (it){ it.c = t.value; cfgChanged(true); toast("زمرہ تبدیل ہو گیا"); } }
});


/* ---------- Dashboard and navigation ---------- */
function focusItems(){
  return items().filter(it => (ui.cat === "all" || it.c === ui.cat) && (!statusOf(it.id) || statusOf(it.id) === "n"));
}
function renderHero(){
  const st = stats(items()), next = items().find(it => !statusOf(it.id) || statusOf(it.id) === "n");
  $("#heroDate").textContent = niceDate(ui.date);
  $("#heroDone").textContent = st.y;
  $("#heroPending").textContent = st.u + st.n;
  $("#heroNA").textContent = st.a;
  $("#nextPreview").textContent = next ? next.t.replace(/\s+/g," ") : "ما شاء اللہ! تمام معمولات کا جائزہ مکمل ہے۔";
}
function updateDock(){
  document.querySelectorAll("[data-bnav]").forEach(b => {
    let active = (b.dataset.bnav === "today" && ui.date === todayIso() && ui.status === "all") ||
                 (b.dataset.bnav === "todo" && ui.status === "todo") ||
                 (b.dataset.bnav === "star" && ui.status === "star");
    if (active) b.setAttribute("aria-current","page"); else b.removeAttribute("aria-current");
  });
}
function clearFilters(){
  ui.q = ""; ui.status = "all"; ui.cat = "all";
  $("#q").value = "";
  renderNav(); renderStatusChips(); renderList(); updateDock();
}
function goToItems(){
  const target = document.querySelector("#mainContent .tools") || document.querySelector("#mainContent");
  target.scrollIntoView({behavior:"smooth",block:"start"});
}
function jumpToItem(id){
  clearFilters();
  const it = items().find(x => x.id === id);
  if (!it) return;
  prefs.closed[it.c] = false; lsSet("prefs",prefs); renderList();
  const el = document.querySelector(`.item[data-id="${CSS.escape(id)}"]`);
  if (el){el.scrollIntoView({behavior:"smooth",block:"center"});el.classList.add("flash");setTimeout(() => el.classList.remove("flash"),2100);}
}

/* ---------- Last 30 days on small screens ---------- */
function openHistory(){
  modal("پچھلے ۳۰ دن", `<p class="muted">کسی دن کے ستون پر دبائیں تاکہ اس دن کا ریکارڈ کھل جائے۔</p>
  <div class="hist" id="modalHist">${$("#hist").innerHTML}</div>
  <div class="hist-axis"><span>${$("#histFrom").textContent}</span><span>${$("#histTo").textContent}</span></div>
  <div class="hist-stats">${$("#histStats").innerHTML}</div>`,(ov, close) => {
    ov.querySelector("#modalHist").addEventListener("click",e => {
      const b=e.target.closest("[data-d]");
      if (b){const d=b.dataset.d;close();setDate(d);}
    });
  });
}

/* ---------- One-step undo ---------- */
let undoEntry = null, undoExpiry = null;
function rememberUndo(date, message){
  undoEntry = {date, snapshot:clone(dayRec(date)), message};
  $("#undoText").textContent = message;
  $("#undoToast").hidden = false;
  clearTimeout(undoExpiry);
  undoExpiry = setTimeout(() => {undoEntry = null; $("#undoToast").hidden = true;},8500);
}
function undoLast(){
  if (!undoEntry) return;
  const entry = undoEntry;
  undoEntry = null; clearTimeout(undoExpiry); $("#undoToast").hidden = true;
  recs[entry.date] = clone(entry.snapshot);
  touchDay(entry.date);
  renderAll(); toast("پچھلا اندراج بحال ہو گیا");
}

/* ---------- Daily focus review ---------- */
function openFocus(){
  if (ui.edit) {toast("فوکس موڈ سے پہلے ترمیم بند کریں"); return;}
  const pool = focusItems().map(it => it.id);
  if (!pool.length){
    modal("فوکس موڈ", `<div class="empty"><h3>ما شاء اللہ، جائزہ مکمل!</h3><p>منتخب زمرے میں مزید کوئی باقی یا رہ جانے والا معمول نہیں۔</p><button class="btn primary" data-close>بند کریں</button></div>`);
    return;
  }
  let current = 0;
  modal("فوکس موڈ · ایک وقت میں ایک معمول", `<div class="focus-panel">
    <div class="focus-step"><b id="focusNum"></b><span>ایک وقت میں ایک معمول</span></div>
    <div class="focus-track"><div id="focusFill"></div></div>
    <div class="focus-card"><span class="category" id="focusCategory"></span><div class="txt" id="focusText"></div><div class="ref" id="focusRef" hidden></div></div>
    <div class="focus-status"><span id="focusCurrent"></span><span>شارٹ کٹ: 1 مکمل · 2 جزوی · 3 رہ گیا · 4 لاگو نہیں</span></div>
    <div class="focus-actions"><button data-focus-status="y">✓ مکمل</button><button data-focus-status="p">◐ جزوی</button><button data-focus-status="n">× رہ گیا</button><button data-focus-status="a">○ لاگو نہیں</button></div>
    <div class="focus-nav"><button class="btn" id="focusPrev">→ پچھلا</button><button class="btn" id="focusJump">اصل فہرست میں دیکھیں</button><button class="btn primary" id="focusNext">اگلا ←</button></div>
  </div>`,(ov,close) => {
    const currentId = () => pool[current];
    function refresh(){
      const it = items().find(x => x.id === currentId());
      if (!it) return;
      ov.querySelector("#focusNum").textContent = `${current+1} / ${pool.length}`;
      ov.querySelector("#focusFill").style.width = ((current+1)/pool.length*100)+"%";
      ov.querySelector("#focusCategory").textContent = `#${items().indexOf(it)+1}  ·  ${catName(it.c)}`;
      ov.querySelector("#focusText").innerHTML = fmtText(it.t,"");
      ov.querySelector("#focusRef").textContent = it.r;
      ov.querySelector("#focusRef").hidden = !it.r;
      ov.querySelector("#focusCurrent").textContent = "موجودہ حالت: " + (ST[statusOf(it.id)] || "ابھی درج نہیں ہوا");
      ov.querySelector("#focusPrev").disabled = current === 0;
      ov.querySelector("#focusNext").disabled = current === pool.length-1;
      ov.querySelectorAll("[data-focus-status]").forEach(b => b.setAttribute("aria-pressed",String(statusOf(it.id) === b.dataset.focusStatus)));
    }
    function mark(v){
      if (ov.isConnected && items().some(x => x.id === currentId())) {
        setStatus(currentId(),v);
        if (current < pool.length-1) current++;
        refresh();
      }
    }
    ov.addEventListener("click", e => {
      const b = e.target.closest("[data-focus-status]");
      if (b) mark(b.dataset.focusStatus);
    });
    ov.querySelector("#focusPrev").addEventListener("click", () => {current=Math.max(0,current-1);refresh();});
    ov.querySelector("#focusNext").addEventListener("click", () => {current=Math.min(pool.length-1,current+1);refresh();});
    ov.querySelector("#focusJump").addEventListener("click", () => {const id=currentId();close();jumpToItem(id);});
    const onKeys = e => {
      if (!ov.isConnected) return;
      if (["INPUT","TEXTAREA","SELECT"].includes(document.activeElement.tagName)) return;
      if (["1","2","3","4"].includes(e.key)){
        e.preventDefault();mark({"1":"y","2":"p","3":"n","4":"a"}[e.key]);
      } else if (e.key === "ArrowLeft" || e.key === "ArrowRight"){
        e.preventDefault(); current=Math.max(0,Math.min(pool.length-1,current+(e.key==="ArrowLeft"?1:-1)));refresh();
      }
    };
    ov.addEventListener("keydown",onKeys);
    refresh();
  });
}

/* ---------- Appearance and reading preferences ---------- */
function openSettings(){
  const options = [["system","نظام کے مطابق"],["light","روشن"],["dark","تاریک"]];
  modal("ظاہری شکل اور مطالعہ", `<p class="muted">آپ کی پسند اسی براؤزر میں محفوظ رہے گی۔</p>
    <strong>رنگوں کا انداز</strong><div class="theme-options">${options.map(([v,l]) => `<button data-theme-choice="${v}" aria-pressed="${(prefs.theme||"system")===v}">${l}</button>`).join("")}</div>
    <div class="reading-controls"><label for="readerSize"><strong>اردو متن کا سائز</strong></label><input type="range" min="0.9" max="1.25" step="0.05" value="${prefs.fontScale}" id="readerSize"/><output id="readerPct" class="num-latin">${Math.round(prefs.fontScale*100)}%</output></div>
    <p class="muted">فونٹ کا سائز صرف مطالعے کے متن پر لاگو ہوتا ہے۔ اصل معمولات میں کوئی تبدیلی نہیں آتی۔</p>
  `,(ov) => {
    ov.addEventListener("click",e => {
      const b=e.target.closest("[data-theme-choice]"); if(!b)return;
      prefs.theme=b.dataset.themeChoice; lsSet("prefs",prefs); applyPrefs();
      ov.querySelectorAll("[data-theme-choice]").forEach(x => x.setAttribute("aria-pressed",String(x===b)));
    });
    ov.querySelector("#readerSize").addEventListener("input",e => {
      prefs.fontScale=+e.target.value; lsSet("prefs",prefs); applyPrefs();
      ov.querySelector("#readerPct").textContent=Math.round(prefs.fontScale*100)+"%";
    });
  });
}

$("#focusBtn").addEventListener("click",openFocus);
$("#remainingBtn").addEventListener("click",() => {ui.status="todo";renderStatusChips();renderList();updateDock();goToItems();});
$("#undoBtn").addEventListener("click",undoLast);
$("#resetFiltersBtn").addEventListener("click",clearFilters);
